<form class="theme-search" action="{{ route('theme.product-search') }}" method="get" role="search" data-product-search><label class="theme-sr-only" for="theme-product-search">{{ $settings['label'] ?? 'جستجوی محصولات' }}</label><input id="theme-product-search" name="q" type="search" value="{{ request('q') }}" placeholder="{{ $settings['placeholder'] ?? 'جستجو در محصولات...' }}" autocomplete="off"><span class="theme-search__icon" aria-hidden="true">⌕</span><div class="theme-search__results" data-search-results hidden></div></form>
